def authenticate_user() -> None:
    """Authenticate user."""
    logger.info("Authenticating user")
    global WS_AUTH_SUCCESS, WS_USERNAME, WS_PASSWORD, WS_AUTH_RESULT
    WS_AUTH_SUCCESS = 'N'
    WS_AUTH_RESULT = authuser(WS_USERNAME, WS_PASSWORD)
    if WS_AUTH_RESULT == 'SUCCESS':
        WS_AUTH_SUCCESS = 'Y'
        create_session()
    else:
        log_failed_auth()

